/** Self-instrumenting library APK: all identities/data are fictional and its UID is separate. */
class MigrationTestRunner:Instrumentation(){
 private var phase="startup"
 private var mode="normal"
 override fun onCreate(arguments:Bundle?){super.onCreate(arguments);mode=arguments?.getString("migrationMode")?:"normal";start()}
 override fun onStart(){val result=Bundle();try{if(mode=="fallback-normal"){SourceFallbackChecks.run(targetContext){phase=it};result.putString("stream","MC_RESULT=PASS fallback-normal");finish(Activity.RESULT_OK,result);return};if(mode=="service-reopen"){OfflineStore.attach(targetContext){NativeTrackResolver.resolve(targetContext,it,false)};val field=OfflineStore.javaClass.getDeclaredField("recovering").apply{isAccessible=true};val deadline=System.currentTimeMillis()+5000;while(field.getBoolean(OfflineStore)){check(System.currentTimeMillis()<deadline);Thread.sleep(50)};result.putString("stream","MC_RESULT=PASS service-reopen");finish(Activity.RESULT_OK,result);return};if(mode=="service-seed"){TransferLifecycleChecks.serviceSeed(targetContext);result.putString("stream","MC_RESULT=SEEDED service-seed");finish(Activity.RESULT_OK,result);return};if(mode in setOf("audio-normal","artwork-normal")){if(mode=="audio-normal")AudioArtworkChecks.audio(targetContext){phase=it}else AudioArtworkChecks.artwork(targetContext){phase=it};result.putString("stream","MC_RESULT=PASS "+mode);finish(Activity.RESULT_OK,result);return};if(mode.startsWith("transfer-")){if(mode=="transfer-normal")TransferLifecycleChecks.run(targetContext){phase=it}else TransferLifecycleChecks.cold(targetContext,mode);result.putString("stream",(if(mode.startsWith("transfer-seed-"))"MC_RESULT=SEEDED " else "MC_RESULT=PASS ")+mode);finish(Activity.RESULT_OK,result);return};if(mode!="normal"){coldCheck();result.putString("stream",if(mode.startsWith("seed-"))"MC_RESULT=SEEDED "+mode else "MC_RESULT=PASS "+mode);finish(Activity.RESULT_OK,result);return};runChecks();result.putString("mc_result","PASS");result.putString("stream","MC_RESULT=PASS Migration native runtime checks passed: encrypted export, preview, restore, fresh-install refusal, wrong password, rollback and restart recovery.");finish(Activity.RESULT_OK,result)}catch(e:Throwable){result.putString("mc_result","FAIL");result.putString("stream","MC_RESULT=FAIL phase="+phase+" type="+e.javaClass.simpleName+" message="+e.message+" frames="+e.stackTrace.take(8).joinToString(" | "));finish(Activity.RESULT_CANCELED,result)}}
 private fun preferences(c:Context,n:String)=c.getSharedPreferences(n,Context.MODE_PRIVATE)
 private fun reset(c:Context){check(c.packageName=="local.mediacenter.library.test"){"Disposable test package required"};NativeBackup.discard();for(n in BackupData.preferences)check(preferences(c,n).edit().clear().commit());val keys=java.security.KeyStore.getInstance("AndroidKeyStore");keys.load(null);keys.deleteEntry("media_center_library_v1");BackupTables.replace(c,BackupTables.empty());for(folder in BackupArchive.folders){val dir=File(c.filesDir,folder);check(dir.canonicalPath.startsWith(c.filesDir.canonicalPath+File.separator));if(dir.exists())check(dir.deleteRecursively())};for(n in listOf("migration-rollback.json","migration-rollback.json.bak","migration-rollback.json.new"))File(c.filesDir,n).delete()}
 private fun seed(c:Context){
  phase="seed accounts";EncryptedAccounts.write(c,"migration-fixture",JSONObject().put("id","migration-fixture").put("type","navidrome").put("name","Fictional library").put("url","https://fixture.invalid").put("username","fixture").put("password","fictional-secret"))
  EncryptedAccounts.write(c,"spoken-fixture",JSONObject().put("id","spoken-fixture").put("type","audiobookshelf").put("name","Fictional spoken library").put("url","https://spoken.invalid").put("username","").put("password","").put("authMode","apiKey").put("accessToken","fictional-api-key"))
  phase="seed preferences and assets";val recipe=JSONObject().put("id","fixture-mix").put("name","Fictional daily mix").put("refresh","daily").put("sources",JSONArray().put("migration-fixture")).put("genres",JSONArray()).put("artists",JSONArray()).put("count",10).put("seed",1).put("familiarity","balanced")
  val rows=JSONArray().put(JSONObject().put("account","migration-fixture").put("id","tone").put("title","Fictional tone").put("artist","Generated artist").put("duration",30))
  val ui=JSONObject().put("palette","plum").put("material","solid").put("likes",JSONArray().put("migration-fixture:tone")).put("personalPlaylists",JSONArray().put(JSONObject().put("id","fixture-playlist").put("name","Fictional favorites").put("tracks",rows))).put("mixRecipes",JSONArray().put(recipe)).put("bookmarks",JSONArray().put(JSONObject().put("key","spoken-fixture:book").put("position",42).put("title","Saved point").put("created",1))).put("pins",JSONArray()).put("backgroundOfflineRules",true).put("cacheAhead",3)
  check(preferences(c,"media_library").edit().putString("ui",ui.toString()).putString("audio",AudioOptions().json().toString()).commit())
  val lyrics="[00:00.00]Fictional lyric";check(preferences(c,"custom_lyrics").edit().putString("migration-fixture:tone",lyrics).commit())
  val cover=CustomizationData.key("migration-fixture","tone");val version="$cover-fixture.image";File(c.filesDir,"custom-covers").mkdirs();File(c.filesDir,"custom-covers/$version").writeBytes(Base64.decode("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+jRZkAAAAASUVORK5CYII=",Base64.DEFAULT));check(preferences(c,"custom_covers").edit().putString(cover,version).commit())
  File(c.filesDir,"spoken-transcripts").mkdirs();File(c.filesDir,"spoken-transcripts/"+CustomizationData.key("transcript","spoken-fixture:book")+".txt").writeText("00:00 A fictional transcript")
  File(c.filesDir,"mix-snapshots").mkdirs();val d=MixSnapshotPlan.definition(recipe);File(c.filesDir,"mix-snapshots/"+BackupArchive.digest(d.id.toByteArray())+".json").writeText(JSONObject().put("fingerprint",d.fingerprint).put("period",d.period(System.currentTimeMillis())).put("updated",1).put("rows",rows).toString())
  phase="seed history and inbox";val tables=BackupTables.empty();tables.getJSONArray("history").put(JSONArray().put("[\"migration-fixture\",\"music\",\"tone\"]").put(rows.getJSONObject(0).put("kind","music").toString()).put(55.5).put(2).put(100))
  val rule=PodcastInboxRule("spoken-fixture","show","Fictional show",enabled=true,autoCache=true);tables.getJSONArray("rules").put(JSONArray(listOf(rule.key,rule.account,rule.show,rule.json().toString(),123,"")));tables.getJSONArray("seen").put(JSONArray(listOf("spoken-fixture","show","episode")))
  val episode=JSONObject().put("account","spoken-fixture").put("show","show").put("episode","episode").put("kind","episode").put("title","Fictional episode").put("showTitle","Fictional show").put("duration",30)
  tables.getJSONArray("inbox").put(JSONArray(listOf(PodcastInboxStore.identity(episode),"spoken-fixture","show","episode",episode.toString(),"fictional episode",1,0,100,"auto","pending","",0)));BackupTables.replace(c,tables)
 }
 private fun coldCheck(){
  val c=targetContext;check(c.packageName=="local.mediacenter.library.test");require(mode in setOf("seed-uncommitted","verify-uncommitted","seed-committed","verify-committed"));val file=File(c.filesDir,"migration-rollback.json")
  phase=mode
  if(mode=="seed-uncommitted"){
   reset(c);val baseline=JSONObject().apply{for(p in BackupData.preferences)put(p,JSONObject());getJSONObject("media_library").put("ui","{\"palette\":\"midnight\"}")};seed(c);File(c.filesDir,"spoken-transcripts/staged.txt").writeText("uncommitted")
   val paths=JSONArray();for(folder in BackupArchive.folders)for(f in File(c.filesDir,folder).listFiles().orEmpty())if(f.isFile)paths.put(folder+"/"+f.name)
   file.writeText(JSONObject().put("preferences",baseline).put("paths",paths).put("committed",false).toString());check(file.exists());return
  }
  if(mode=="seed-committed"){
   reset(c);seed(c);val uri=Uri.parse("content://local.mediacenter.library.test.migration/fixture.mcbackup");val password="fixture-backup-password".toCharArray();NativeBackup.export(c,uri,password);reset(c);val preview=JSONObject(NativeBackup.preview(c,uri,password));NativeBackup.apply(c,preview.getString("token"));password.fill('\u0000');check(file.exists());return
  }
  check(file.exists());check(preferences(c,"media_library").contains("account.migration-fixture"));NativeBackup.recoverOnLaunch(c);check(NativeBackup.recoveryError.isEmpty());check(!file.exists())
  if(mode=="verify-uncommitted"){check(preferences(c,"media_library").all.keys.none{it.startsWith("account.")});check(JSONObject(preferences(c,"media_library").getString("ui","{}")!!).getString("palette")=="midnight");check(BackupTables.snapshot(c).getJSONArray("history").length()==0);for(folder in BackupArchive.folders)check(File(c.filesDir,folder).listFiles().orEmpty().isEmpty())}
  else{check(EncryptedAccounts.read(c,"migration-fixture").getString("password")=="fictional-secret");check(BackupTables.snapshot(c).getJSONArray("history").length()==1);check(File(c.filesDir,"custom-covers").listFiles().orEmpty().isNotEmpty())}
  reset(c);File(c.cacheDir,"fixture.mcbackup").delete()
 }
 private fun runChecks(){
  val c=targetContext;check(c.packageName=="local.mediacenter.library.test");val uri=Uri.parse("content://local.mediacenter.library.test.migration/fixture.mcbackup");val password="fixture-backup-password".toCharArray()
  phase="independent Unicode password encryption vector";val vector=Base64.decode("TUNCQUNLVVAxAAECAwQFBgcICQoLDA0ODxAREhMUFRYXGBkaG76wx73quBpTZaypJNxl6kXzHOIvmP/fnLUIKILpULmHM2JVyNfgDrcrncNwGYyLaA==",Base64.DEFAULT);check(String(BackupCipher.decrypt(vector,"fixture-pässword-测试".toCharArray()),Charsets.UTF_8)=="Media Center portable backup ✓")
  phase="seed";reset(c);seed(c);phase="native encrypted export";val originalCredential=preferences(c,"media_library").getString("account.migration-fixture",null)!!;NativeBackup.export(c,uri,password);val encrypted=File(c.cacheDir,"fixture.mcbackup").readBytes();check(!String(encrypted,Charsets.ISO_8859_1).contains("fictional-secret"));check(encrypted.size>100)
  phase="queued unloaded audio refuses backup";val queue=Playback::class.java.getDeclaredField("queue").apply{isAccessible=true};val previousQueue=queue.get(null);try{queue.set(null,listOf(Playable("migration-fixture","queued","Pending","","","","",0.0)));check(runCatching{NativeBackup.export(c,uri,password)}.isFailure);check(File(c.cacheDir,"fixture.mcbackup").readBytes().contentEquals(encrypted))}finally{queue.set(null,previousQueue)}
  phase="open video refuses backup";val leases=VideoActivity::class.java.getDeclaredField("leases").apply{isAccessible=true}.get(null) as MutableSet<String>;leases.add("fixture-video");try{check(runCatching{NativeBackup.export(c,uri,password)}.isFailure);check(File(c.cacheDir,"fixture.mcbackup").readBytes().contentEquals(encrypted))}finally{leases.remove("fixture-video")}
  phase="existing installation verification is read-only";val readOnly=JSONObject(NativeBackup.preview(c,uri,password));check(readOnly.getBoolean("verified")&&!readOnly.getBoolean("canRestore")&&!readOnly.has("token"));check(runCatching{NativeBackup.apply(c,"not-a-preview")}.isFailure);check(EncryptedAccounts.read(c,"migration-fixture").getString("password")=="fictional-secret")
  phase="wrong password leaves fresh destination unchanged";reset(c);check(runCatching{NativeBackup.preview(c,uri,"different-password".toCharArray())}.isFailure);check(preferences(c,"media_library").all.isEmpty());check(BackupTables.snapshot(c).getJSONArray("history").length()==0)
  phase="invalid image is rejected before any restore";val original=BackupArchive.unpack(BackupCipher.decrypt(encrypted,password));val badAssets=original.assets.toMutableMap();val badCover=badAssets.keys.first{it.startsWith("custom-covers/")};badAssets[badCover]="not an image".toByteArray();File(c.cacheDir,"fixture.mcbackup").writeBytes(BackupCipher.encrypt(BackupArchive.pack(original.manifest,badAssets),password));check(runCatching{NativeBackup.preview(c,uri,password)}.isFailure);check(preferences(c,"media_library").all.isEmpty());File(c.cacheDir,"fixture.mcbackup").writeBytes(encrypted)
  phase="preview without mutation";val preview=JSONObject(NativeBackup.preview(c,uri,password));check(preview.getInt("accounts")==2&&preview.getInt("history")==1&&preview.getInt("inbox")==1&&preview.getInt("assets")==3);check(preferences(c,"media_library").all.isEmpty())
  phase="confirmed restore and destination Keystore";NativeBackup.apply(c,preview.getString("token"));check(EncryptedAccounts.read(c,"migration-fixture").getString("password")=="fictional-secret");check(EncryptedAccounts.read(c,"spoken-fixture").getString("accessToken")=="fictional-api-key");check(preferences(c,"media_library").getString("account.migration-fixture","")!!.contains(':'))
  phase="old Keystore ciphertext cannot unlock on destination";val destinationCredential=preferences(c,"media_library").getString("account.migration-fixture",null)!!;check(destinationCredential!=originalCredential);check(preferences(c,"media_library").edit().putString("account.migration-fixture",originalCredential).commit());check(runCatching{EncryptedAccounts.read(c,"migration-fixture")}.isFailure);check(preferences(c,"media_library").edit().putString("account.migration-fixture",destinationCredential).commit());check(EncryptedAccounts.read(c,"migration-fixture").getString("password")=="fictional-secret")
  val ui=JSONObject(preferences(c,"media_library").getString("ui","{}")!!);check(ui.getString("palette")=="plum"&&ui.getJSONArray("personalPlaylists").getJSONObject(0).getString("name")=="Fictional favorites");check(!ui.getBoolean("backgroundOfflineRules")&&ui.getInt("cacheAhead")==0);check(preferences(c,"custom_lyrics").getString("migration-fixture:tone","")=="[00:00.00]Fictional lyric");check(File(c.filesDir,"spoken-transcripts/"+CustomizationData.key("transcript","spoken-fixture:book")+".txt").readText().contains("fictional transcript"))
  val tables=BackupTables.snapshot(c);check(tables.getJSONArray("history").getJSONArray(0).getDouble(2)==55.5);val rule=JSONObject(tables.getJSONArray("rules").getJSONArray(0).getString(3));check(!rule.getBoolean("enabled")&&!rule.getBoolean("autoCache"));check(tables.getJSONArray("inbox").getJSONArray(0).getString(10)=="");check(MixSnapshots.operation(c,"get",JSONObject().put("id","fixture-mix")).getJSONArray("rows").length()==1)
  phase="committed restart recovery";NativeBackup.recoverOnLaunch(c);check(NativeBackup.recoveryError.isEmpty());check(EncryptedAccounts.read(c,"migration-fixture").getString("password")=="fictional-secret");check(!File(c.filesDir,"migration-rollback.json").exists())
  phase="failed asset write rolls back earlier database changes";reset(c);check(preferences(c,"media_library").edit().putString("ui","{\"palette\":\"midnight\"}").commit());val failed=JSONObject(NativeBackup.preview(c,uri,password));val blocker=File(c.filesDir,"custom-covers");blocker.writeText("test-owned blocker");check(runCatching{NativeBackup.apply(c,failed.getString("token"))}.isFailure);check(preferences(c,"media_library").all.keys.none{it.startsWith("account.")});check(JSONObject(preferences(c,"media_library").getString("ui","{}")!!).getString("palette")=="midnight");check(BackupTables.snapshot(c).getJSONArray("history").length()==0);check(blocker.readText()=="test-owned blocker");check(NativeBackup.recoveryError.isEmpty())
  phase="uncommitted restart recovery";reset(c);val baseline=JSONObject().apply{for(p in BackupData.preferences)put(p,JSONObject())};File(c.filesDir,"spoken-transcripts").mkdirs();File(c.filesDir,"spoken-transcripts/staged.txt").writeText("uncommitted");EncryptedAccounts.write(c,"partial",JSONObject().put("id","partial").put("password","fictional"));File(c.filesDir,"migration-rollback.json").writeText(JSONObject().put("preferences",baseline).put("paths",JSONArray().put("spoken-transcripts/staged.txt")).put("committed",false).toString());NativeBackup.recoverOnLaunch(c);check(NativeBackup.recoveryError.isEmpty());check(preferences(c,"media_library").all.isEmpty());check(!File(c.filesDir,"spoken-transcripts/staged.txt").exists());check(!File(c.filesDir,"migration-rollback.json").exists())
  phase="corrupt recovery journal stays actionable";File(c.filesDir,"migration-rollback.json").writeText("invalid");NativeBackup.recoverOnLaunch(c);check(NativeBackup.recoveryError.isNotEmpty());check(File(c.filesDir,"migration-rollback.json").exists());check(File(c.filesDir,"migration-rollback.json").delete());NativeBackup.recoverOnLaunch(c);check(NativeBackup.recoveryError.isEmpty())
  phase="cleanup";reset(c);check(File(c.cacheDir,"fixture.mcbackup").delete());password.fill('\u0000')
 }
}
